stack = []
for _ in range(int(input())):
	b = input()
	if b == '-1':
		(num, book, count) = stack.pop()
		print(str(count) + ' ' + book)
	else:
		b = b.split()
		num = int(b[0])
		book = b[1]
		if num != 0:
			if len(stack) == 0:
				stack.append([num, book, 0])
			elif num > stack[-1][0]:
				stack[-1][2] += 1
			else:
				stack.append([num, book, 0])
